def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty)
    sell_book = []  # list of (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_time) for tracking
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, remaining_qty, arr_time = order_map[order_id]
                if remaining_qty > 0:
                    # Remove from book
                    if side == 'buy':
                        buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                    else:
                        sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
                    # Mark as cancelled
                    order_map[order_id] = (side, price, 0, arr_time)

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]
            order_map[order_id] = (side, None, qty, arrival_time)

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest arrival)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                while qty > 0 and sell_book:
                    price, arr, sell_id, sell_qty = sell_book[0]
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, price, trade_qty])
                    qty -= trade_qty
                    sell_qty -= trade_qty

                    if sell_qty == 0:
                        sell_book.pop(0)
                        order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], 0, order_map[sell_id][3])
                    else:
                        sell_book[0] = (price, arr, sell_id, sell_qty)
                        order_map[sell_id] = ('sell', price, sell_qty, order_map[sell_id][3])
            else:
                # Match against buy_book (highest price first, then earliest arrival)
                buy_book.sort(key=lambda x: (-x[0], x[1]))
                while qty > 0 and buy_book:
                    price, arr, buy_id, buy_qty = buy_book[0]
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, price, trade_qty])
                    qty -= trade_qty
                    buy_qty -= trade_qty

                    if buy_qty == 0:
                        buy_book.pop(0)
                        order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], 0, order_map[buy_id][3])
                    else:
                        buy_book[0] = (price, arr, buy_id, buy_qty)
                        order_map[buy_id] = ('buy', price, buy_qty, order_map[buy_id][3])

        elif order[0] in ['limit', 'ioc']:
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]
            order_map[order_id] = (side, price, qty, arrival_time)

