                # Match against sell_book (lowest price first, then earliest arrival)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                while qty > 0 and sell_book:
                    sell_price, arr, sell_id, sell_qty = sell_book[0]
                    if sell_price <= price:
                        trade_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        qty -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty == 0:
                            sell_book.pop(0)
                            order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], 0, order_map[sell_id][3])
                        else:
                            sell_book[0] = (sell_price, arr, sell_id, sell_qty)
                            order_map[sell_id] = ('sell', sell_price, sell_qty, order_map[sell_id][3])
                    else:
                        break

                # Add remainder to book if limit order
                if order[0] == 'limit' and qty > 0:
                    buy_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = (side, price, qty, arrival_time)
                else:
                    order_map[order_id] = (side, price, 0, arrival_time)
            else:
                # Match against buy_book (highest price first, then earliest arrival)
                buy_book.sort(key=lambda x: (-x[0], x[1]))
                while qty > 0 and buy_book:
                    buy_price, arr, buy_id, buy_qty = buy_book[0]
                    if buy_price >= price:
                        trade_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        qty -= trade_qty
                        buy_qty -= trade_qty

                        if buy_qty == 0:
                            buy_book.pop(0)
                            order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], 0, order_map[buy_id][3])
                        else:
                            buy_book[0] = (buy_price, arr, buy_id, buy_qty)
                            order_map[buy_id] = ('buy', buy_price, buy_qty, order_map[buy_id][3])
                    else:
                        break

                # Add remainder to book if limit order
                if order[0] == 'limit' and qty > 0:
                    sell_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = (side, price, qty, arrival_time)
                else:
                    order_map[order_id] = (side, price, 0, arrival_time)

    return trades

